// Reed–Solomon codes — the algebraic block-code pillar of the Coding family, from
// scratch with no libraries. Everything the CD, the QR code, the DVD, the QR on
// your boarding pass and every deep-space probe since Voyager leans on lives here:
//
//   • GF(2^m) finite-field arithmetic built from a primitive polynomial (log/antilog
//     tables generated by walking the field with the generator α = 2), for m = 3…8;
//   • polynomial algebra over that field (add / scale / multiply / Horner eval /
//     synthetic division);
//   • the RS **generator polynomial** g(x) = ∏(x − α^(fcr+i)) and a **systematic
//     encoder** (message · x^{2t} + remainder) so H·c = 0 holds by construction —
//     every codeword is a multiple of g, hence a zero of all 2t check roots;
//   • the full **algebraic decoder**: syndromes S_j = r(α^(fcr+j)); the
//     **Berlekamp–Massey** recursion for the error-locator polynomial Λ(x); a
//     **Chien search** for its roots (the error positions); and the **Forney
//     algorithm** for the error magnitudes (Ω(x) = S(x)Λ(x) mod x^{2t}, y = Ω/Λ′);
//   • **errors *and* erasures** together — an erasure locator seeds Λ and the Forney
//     syndromes let Berlekamp–Massey solve only for the unknown-location errors, so
//     the code corrects any e errors + f erasures with 2e + f ≤ 2t.
//
// Convention. A polynomial is a plain `number[]` of field elements, **index 0 = the
// highest-degree coefficient** (the "reedsolo" convention). A codeword c[0..n-1] is
// c(x) = Σ c[i]·x^{n-1-i}; the symbol at array index i therefore sits at *degree*
// n-1-i, so its error-locator value is X = α^{n-1-i}. Syndrome S_j = c(α^{fcr+j}).
// This module is the source of truth for the Reed–Solomon lab (modes/ReedSolomon).

// ---------------------------------------------------------------------------
// GF(2^m) — the finite field.
// ---------------------------------------------------------------------------

export interface GF {
  /** bits per symbol (field is GF(2^m)). */
  m: number
  /** number of field elements, 2^m. */
  size: number
  /** the order of the multiplicative group, size − 1. */
  order: number
  /** the primitive polynomial (including the x^m bit), e.g. 0x11D for m = 8. */
  prim: number
  /** antilog table: exp[i] = α^i. Doubled in length so exp[log a + log b] never wraps. */
  exp: Uint16Array
  /** log table: log[x] = i with α^i = x (log[0] is unused / −∞). */
  log: Uint16Array
}

/**
 * Build a GF(2^m) field from a primitive polynomial, with α = 2 as the generator.
 * Walking x ← x·α (a shift, reduced mod `prim` on overflow) enumerates the whole
 * multiplicative group because α = 2 is primitive for every polynomial below.
 */
export function makeField(m: number, prim: number): GF {
  const size = 1 << m
  const order = size - 1
  const exp = new Uint16Array(2 * size)
  const log = new Uint16Array(size)
  let x = 1
  for (let i = 0; i < order; i++) {
    exp[i] = x
    log[x] = i
    x <<= 1
    if (x & size) x ^= prim
  }
  // Duplicate the cycle so exp can be indexed by log[a] + log[b] (≤ 2·order − 2)
  // without a modulo in the hot multiply path.
  for (let i = order; i < 2 * size; i++) exp[i] = exp[i - order]
  return { m, size, order, prim, exp, log }
}

/** Standard primitive polynomials (α = 2 is primitive for each). */
export const PRIMITIVE_POLYS: Record<number, number> = {
  3: 0x0b, // x^3 + x + 1
  4: 0x13, // x^4 + x + 1
  5: 0x25, // x^5 + x^2 + 1
  6: 0x43, // x^6 + x + 1
  8: 0x11d, // x^8 + x^4 + x^3 + x^2 + 1  (the CD / QR / CCSDS field)
}

/** Convenience: the field GF(2^m) with its canonical primitive polynomial. */
export function fieldOf(m: number): GF {
  const prim = PRIMITIVE_POLYS[m]
  if (!prim) throw new Error(`no primitive polynomial registered for GF(2^${m})`)
  return makeField(m, prim)
}

export const gfAdd = (a: number, b: number): number => a ^ b // subtraction is identical in GF(2^m)

export function gfMul(f: GF, a: number, b: number): number {
  if (a === 0 || b === 0) return 0
  return f.exp[f.log[a] + f.log[b]]
}

export function gfDiv(f: GF, a: number, b: number): number {
  if (b === 0) throw new Error('GF divide by zero')
  if (a === 0) return 0
  return f.exp[f.log[a] + f.order - f.log[b]]
}

export function gfInv(f: GF, a: number): number {
  if (a === 0) throw new Error('GF inverse of zero')
  return f.exp[f.order - f.log[a]]
}

/** α^n for any (possibly negative) integer exponent n. */
export function gfPow(f: GF, a: number, n: number): number {
  if (a === 0) return n === 0 ? 1 : 0
  let e = (f.log[a] * n) % f.order
  if (e < 0) e += f.order
  return f.exp[e]
}

// ---------------------------------------------------------------------------
// Polynomials over GF(2^m) — index 0 = highest-degree coefficient.
// ---------------------------------------------------------------------------

/** Drop leading (high-degree) zeros so a poly has a well-defined degree. */
export function polyTrim(p: number[]): number[] {
  let i = 0
  while (i < p.length - 1 && p[i] === 0) i++
  return p.slice(i)
}

export function polyScale(f: GF, p: number[], s: number): number[] {
  return p.map((c) => gfMul(f, c, s))
}

export function polyAdd(a: number[], b: number[]): number[] {
  const out = new Array(Math.max(a.length, b.length)).fill(0)
  for (let i = 0; i < a.length; i++) out[i + out.length - a.length] = a[i]
  for (let i = 0; i < b.length; i++) out[i + out.length - b.length] ^= b[i]
  return out
}

export function polyMul(f: GF, a: number[], b: number[]): number[] {
  const out = new Array(a.length + b.length - 1).fill(0)
  for (let i = 0; i < a.length; i++) {
    if (a[i] === 0) continue
    for (let j = 0; j < b.length; j++) {
      if (b[j] === 0) continue
      out[i + j] ^= gfMul(f, a[i], b[j])
    }
  }
  return out
}

/** Horner evaluation p(x). */
export function polyEval(f: GF, p: number[], x: number): number {
  let y = p[0]
  for (let i = 1; i < p.length; i++) y = gfAdd(gfMul(f, y, x), p[i])
  return y
}

/**
 * Synthetic division of `dividend` by `divisor`, both index-0-high. Returns the
 * quotient and remainder (the remainder occupies the low `deg(divisor)` slots).
 */
export function polyDivmod(f: GF, dividend: number[], divisor: number[]): { q: number[]; r: number[] } {
  const out = dividend.slice()
  const dl = divisor.length
  const lead = divisor[0]
  for (let i = 0; i < dividend.length - (dl - 1); i++) {
    const coef = out[i]
    if (coef === 0) continue
    const norm = lead === 1 ? coef : gfDiv(f, coef, lead)
    out[i] = norm
    for (let j = 1; j < dl; j++) {
      if (divisor[j] !== 0) out[i + j] ^= gfMul(f, divisor[j], norm)
    }
  }
  const sep = dividend.length - (dl - 1)
  return { q: out.slice(0, sep), r: out.slice(sep) }
}

// ---------------------------------------------------------------------------
// Reed–Solomon code definition.
// ---------------------------------------------------------------------------

export interface RSCode {
  id: string
  label: string
  /** the field GF(2^m). */
  field: GF
  /** block length in symbols (n ≤ 2^m − 1; n < order ⇒ a *shortened* code). */
  n: number
  /** message length in symbols. */
  k: number
  /** parity symbols, nsym = n − k = 2t. */
  nsym: number
  /** correction power t = ⌊nsym / 2⌋. */
  t: number
  /** first consecutive root exponent (the roots are α^fcr … α^{fcr+nsym−1}). */
  fcr: number
  note: string
}

/** Assemble an RS(n, k) code over GF(2^m) with fcr consecutive roots from α^fcr. */
export function makeRS(
  id: string,
  label: string,
  m: number,
  n: number,
  k: number,
  fcr: number,
  note: string,
): RSCode {
  const field = fieldOf(m)
  if (n > field.order) throw new Error(`n=${n} exceeds 2^${m}−1=${field.order}`)
  if (k >= n) throw new Error('k must be < n')
  const nsym = n - k
  return { id, label, field, n, k, nsym, t: nsym >> 1, fcr, note }
}

/** The catalogue: real deployed codes plus small fields you can watch symbol-by-symbol. */
export const RS_CODES: RSCode[] = [
  makeRS('rs7_3', 'RS(7,3) · GF(8)', 3, 7, 3, 1, 'the tiniest full RS — t=2, every symbol on screen'),
  makeRS('rs15_11', 'RS(15,11) · GF(16)', 4, 15, 11, 1, 'the teaching code — t=2, a nibble per symbol'),
  makeRS('rs15_9', 'RS(15,9) · GF(16)', 4, 15, 9, 1, 't=3, half a byte-field'),
  makeRS('rs31_25', 'RS(31,25) · GF(32)', 5, 31, 25, 1, 't=3 over GF(32)'),
  makeRS('rs255_251', 'RS(255,251) · GF(256)', 8, 255, 251, 1, 't=2, the lightest byte-field code'),
  makeRS('rs255_239', 'RS(255,239) · GF(256)', 8, 255, 239, 1, 't=8 — the DVB / storage workhorse'),
  makeRS('rs255_223', 'RS(255,223) · GF(256)', 8, 255, 223, 1, 't=16 — the CCSDS / Voyager deep-space outer code'),
]

export function rsById(id: string): RSCode {
  const c = RS_CODES.find((x) => x.id === id)
  if (!c) throw new Error(`unknown RS code ${id}`)
  return c
}

// ---------------------------------------------------------------------------
// Encoding.
// ---------------------------------------------------------------------------

/** The monic RS generator g(x) = ∏_{i=0}^{nsym−1} (x − α^{fcr+i}). */
export function rsGenerator(code: RSCode): number[] {
  const f = code.field
  let g = [1]
  for (let i = 0; i < code.nsym; i++) {
    g = polyMul(f, g, [1, gfPow(f, 2, code.fcr + i)])
  }
  return g
}

/**
 * Systematic encode. `msg` is k data symbols (index 0 = highest degree). Returns
 * the full n-symbol codeword: the data unchanged, followed by nsym parity symbols
 * = (msg · x^{nsym}) mod g(x). The result is divisible by g, so every check root is
 * a zero of the codeword.
 */
export function rsEncode(code: RSCode, msg: ArrayLike<number>, gen?: number[]): number[] {
  if (msg.length !== code.k) throw new Error(`message must be exactly ${code.k} symbols`)
  const f = code.field
  const g = gen ?? rsGenerator(code)
  // Synthetic division of [msg, 0×nsym] by g, reading the remainder off the tail.
  const out = new Array(code.n).fill(0)
  for (let i = 0; i < code.k; i++) out[i] = msg[i]
  for (let i = 0; i < code.k; i++) {
    const coef = out[i]
    if (coef === 0) continue
    for (let j = 1; j < g.length; j++) {
      out[i + j] ^= gfMul(f, g[j], coef) // g is monic ⇒ g[0] = 1, no normalisation
    }
  }
  // out[0..k-1] were clobbered by the division; restore the data half.
  for (let i = 0; i < code.k; i++) out[i] = msg[i]
  return out
}

/** Split a codeword into its data and parity halves. */
export function rsParity(code: RSCode, codeword: number[]): { data: number[]; parity: number[] } {
  return { data: codeword.slice(0, code.k), parity: codeword.slice(code.k) }
}

// ---------------------------------------------------------------------------
// Decoding — syndromes, Berlekamp–Massey, Chien, Forney, with erasures.
// ---------------------------------------------------------------------------

/** Syndromes S_j = r(α^{fcr+j}), j = 0…nsym−1. All zero ⇔ r is a codeword. */
export function rsSyndromes(code: RSCode, r: ArrayLike<number>): number[] {
  const f = code.field
  const rp = Array.from(r)
  const synd = new Array(code.nsym)
  for (let j = 0; j < code.nsym; j++) synd[j] = polyEval(f, rp, gfPow(f, 2, code.fcr + j))
  return synd
}

/**
 * The errata locator ∏ (1 − α^{d_i}·x) for a set of *degree* positions d_i, stored
 * index-0-high. (Used both to seed erasures and to build the final Λ.)
 */
function errataLocator(f: GF, degrees: number[]): number[] {
  let e = [1]
  for (const d of degrees) e = polyMul(f, e, [gfPow(f, 2, d), 1]) // (α^d · x + 1)
  return e
}

/**
 * Forney syndromes: fold the erasures out of the syndrome sequence so
 * Berlekamp–Massey only has to solve for the unknown-location errors. `degs` are
 * the erasure *degree* positions (n−1−index).
 */
function forneySyndromes(f: GF, synd: number[], degs: number[]): number[] {
  const fs = synd.slice()
  for (const d of degs) {
    const x = gfPow(f, 2, d)
    for (let j = 0; j < fs.length - 1; j++) fs[j] = gfAdd(gfMul(f, fs[j], x), fs[j + 1])
  }
  return fs
}

/**
 * Berlekamp–Massey on the (Forney) syndromes, returning the error-locator
 * polynomial Λ(x) (index-0-high). Because the erasures have already been folded
 * out into the Forney syndromes, this is a *plain* BM that solves only for the
 * unknown-location errors — but it consumes only the first `nsym − f` modified
 * syndromes (pass that count as `count`), the redundancy the erasures left behind.
 */
export function berlekampMassey(f: GF, synd: number[], count = synd.length): number[] {
  // Work index-0-LOW here (the natural BM direction), reversing on return.
  let C = [1] // current locator, low-degree first
  let B = [1] // last locator before the last length change
  let L = 0
  let mm = 1
  let b = 1
  const N = Math.max(0, Math.min(count, synd.length))
  for (let n = 0; n < N; n++) {
    // discrepancy δ = S_n + Σ C_i S_{n−i}
    let delta = synd[n]
    for (let i = 1; i <= L; i++) delta = gfAdd(delta, gfMul(f, C[i], synd[n - i]))
    if (delta === 0) {
      mm++
    } else if (2 * L <= n) {
      const T = C.slice()
      const scale = gfDiv(f, delta, b)
      const shifted = shiftLow(B, mm)
      C = polyAddLow(C, polyScaleLow(f, shifted, scale))
      L = n + 1 - L
      B = T
      b = delta
      mm = 1
    } else {
      const scale = gfDiv(f, delta, b)
      const shifted = shiftLow(B, mm)
      C = polyAddLow(C, polyScaleLow(f, shifted, scale))
      mm++
    }
  }
  // Return index-0-HIGH.
  return C.slice().reverse()
}

// --- little index-0-LOW helpers for Berlekamp–Massey ------------------------
function shiftLow(p: number[], k: number): number[] {
  const out = new Array(k).fill(0)
  return out.concat(p)
}
function polyScaleLow(f: GF, p: number[], s: number): number[] {
  return p.map((c) => gfMul(f, c, s))
}
function polyAddLow(a: number[], b: number[]): number[] {
  const out = new Array(Math.max(a.length, b.length)).fill(0)
  for (let i = 0; i < a.length; i++) out[i] ^= a[i]
  for (let i = 0; i < b.length; i++) out[i] ^= b[i]
  return out
}

/**
 * Chien search: the error positions are the array indices i whose locator value
 * α^{n−1−i} is a root of Λ. Returns the array indices (0…n−1) of the errors.
 */
export function chienSearch(code: RSCode, errLoc: number[]): number[] {
  const f = code.field
  const positions: number[] = []
  for (let i = 0; i < code.n; i++) {
    const deg = code.n - 1 - i
    // Λ(α^{−deg}) == 0 ⇔ α^{deg} is a root of the reciprocal.
    if (polyEval(f, errLoc, gfPow(f, 2, -deg)) === 0) positions.push(i)
  }
  return positions
}

export interface RSDecode {
  /** the corrected codeword (may equal the input if it was already valid). */
  corrected: number[]
  /** true if decoding produced a valid codeword (all syndromes zero afterwards). */
  ok: boolean
  /** the syndromes of the *received* word (before correction). */
  syndromes: number[]
  /** the error-locator polynomial Λ(x), index-0-high (empty if not computed). */
  errLoc: number[]
  /** array indices that were corrected (errors ∪ erasures actually applied). */
  errPositions: number[]
  /** the magnitude XORed into each corrected position (parallel to errPositions). */
  magnitudes: number[]
  /** number of symbol errors the decoder located and fixed (excludes clean erasures). */
  errorsCorrected: number
}

/**
 * The full errors-and-erasures decoder. `received` is n symbols; `erasures` is a
 * list of array indices whose value is unknown (they are treated as 0 going in but
 * their *location* is known, doubling their value to the code). Corrects any e
 * errors and f erasures with 2e + f ≤ nsym; sets `ok = false` when the error
 * weight exceeds that budget (a detected, uncorrectable block).
 */
export function rsDecode(code: RSCode, received: ArrayLike<number>, erasures: number[] = []): RSDecode {
  const f = code.field
  const r = Array.from(received)
  const fail = (syndromes: number[]): RSDecode => ({
    corrected: r.slice(),
    ok: false,
    syndromes,
    errLoc: [],
    errPositions: [],
    magnitudes: [],
    errorsCorrected: 0,
  })

  // Erased symbols are unknown — force them to 0 before syndromes.
  const erasureSet = [...new Set(erasures)].filter((p) => p >= 0 && p < code.n)
  for (const p of erasureSet) r[p] = 0

  const synd = rsSyndromes(code, r)
  if (synd.every((s) => s === 0)) {
    // Already a valid codeword (or the erasures happened to be zero).
    return { corrected: r.slice(), ok: true, syndromes: synd, errLoc: [1], errPositions: [], magnitudes: [], errorsCorrected: 0 }
  }
  if (erasureSet.length > code.nsym) return fail(synd)

  const erasureDegs = erasureSet.map((p) => code.n - 1 - p)
  // Fold erasures out, solve the residual with Berlekamp–Massey. The erasures spend
  // f of the nsym syndromes, so BM runs on the first nsym − f Forney syndromes.
  const fsynd = forneySyndromes(f, synd, erasureDegs)
  const errLoc = berlekampMassey(f, fsynd, code.nsym - erasureSet.length)
  const errorCount = polyTrim(errLoc).length - 1

  // Locate the unknown errors, add back the known erasure locations.
  const errPos = errorCount > 0 ? chienSearch(code, errLoc) : []
  if (errPos.length !== errorCount) return fail(synd) // Chien disagreed with deg Λ ⇒ too many errors

  const allPos = [...new Set([...erasureSet, ...errPos])]
  if (2 * errorCount + erasureSet.length > code.nsym) return fail(synd)

  // Forney magnitudes over the full errata locator.
  const allDegs = allPos.map((p) => code.n - 1 - p)
  const lambda = errataLocator(f, allDegs) // index-0-high
  const magnitudes = forneyMagnitudes(code, synd, lambda, allPos, allDegs)

  const corrected = r.slice()
  for (let i = 0; i < allPos.length; i++) corrected[allPos[i]] ^= magnitudes[i]

  const check = rsSyndromes(code, corrected)
  const ok = check.every((s) => s === 0)
  return {
    corrected,
    ok,
    syndromes: synd,
    errLoc: polyTrim(lambda),
    errPositions: ok ? allPos : [],
    magnitudes: ok ? magnitudes : [],
    errorsCorrected: errorCount,
  }
}

/**
 * Forney's algorithm. Ω(x) = [S(x)·Λ(x)] mod x^{nsym} is the error evaluator; the
 * magnitude at position with locator X_i = α^{deg_i} is
 *   e_i = X_i^{1−fcr} · Ω(X_i^{−1}) / Λ′(X_i^{−1}),
 * with Λ′ the formal derivative (only odd-graded terms survive in char 2).
 */
function forneyMagnitudes(
  code: RSCode,
  synd: number[],
  lambda: number[],
  positions: number[],
  degs: number[],
): number[] {
  const f = code.field
  // S(x) index-0-high with S_0 the highest term (matches Λ so the product aligns).
  const Srev = synd.slice().reverse()
  const prod = polyMul(f, Srev, lambda)
  // Ω = the low nsym coefficients of the product (i.e. mod x^{nsym}).
  const omega = prod.slice(Math.max(0, prod.length - code.nsym))

  const mags: number[] = []
  for (let i = 0; i < positions.length; i++) {
    const Xi = gfPow(f, 2, degs[i])
    const XiInv = gfInv(f, Xi)
    const omegaVal = polyEval(f, omega, XiInv)
    // Λ′(X_i^{-1}): formal derivative in GF(2^m) keeps only odd-power terms.
    // lambda is index-0-high of degree L; term c·x^p contributes p·c·x^{p-1},
    // which is c·x^{p-1} when p is odd and 0 when p is even.
    const L = lambda.length - 1
    let deriv = 0
    for (let p = 1; p <= L; p++) {
      if (p & 1) {
        const c = lambda[lambda.length - 1 - p] // coefficient of x^p
        deriv = gfAdd(deriv, gfMul(f, c, gfPow(f, XiInv, p - 1)))
      }
    }
    if (deriv === 0) {
      mags.push(0)
      continue
    }
    let y = gfDiv(f, omegaVal, deriv)
    if (code.fcr !== 1) y = gfMul(f, y, gfPow(f, Xi, 1 - code.fcr))
    mags.push(y)
  }
  return mags
}

// ---------------------------------------------------------------------------
// Closed-form performance — the theory curves the Monte-Carlo must land on.
// ---------------------------------------------------------------------------

/** log C(n, k) via lgamma, so n = 255 never overflows. */
function lnChoose(n: number, k: number): number {
  if (k < 0 || k > n) return -Infinity
  return lgamma(n + 1) - lgamma(k + 1) - lgamma(n - k + 1)
}

// Lanczos approximation to ln Γ(x) (x > 0).
function lgamma(x: number): number {
  const g = 7
  const c = [
    0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313,
    -176.61502916214059, 12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6,
    1.5056327351493116e-7,
  ]
  if (x < 0.5) return Math.log(Math.PI / Math.sin(Math.PI * x)) - lgamma(1 - x)
  x -= 1
  let a = c[0]
  const tt = x + g + 0.5
  for (let i = 1; i < g + 2; i++) a += c[i] / (x + i)
  return 0.5 * Math.log(2 * Math.PI) + (x + 0.5) * Math.log(tt) - tt + Math.log(a)
}

/**
 * Codeword (block) error probability of a t-error-correcting RS code on a channel
 * that corrupts each symbol independently with probability p_s: the block fails
 * exactly when more than t symbols are wrong.
 *   P_block = Σ_{i=t+1}^{n} C(n,i) p_s^i (1−p_s)^{n−i}.
 */
export function rsBlockErrorProb(code: RSCode, ps: number): number {
  if (ps <= 0) return 0
  if (ps >= 1) return 1
  const n = code.n
  let sum = 0
  const lp = Math.log(ps)
  const lq = Math.log(1 - ps)
  for (let i = code.t + 1; i <= n; i++) {
    sum += Math.exp(lnChoose(n, i) + i * lp + (n - i) * lq)
  }
  return Math.min(1, sum)
}

/**
 * The output symbol-error probability after decoding (a standard bound / estimate):
 * when the block is uncorrectable the decoder is modelled as leaving those symbols
 * wrong, so the expected residual symbol-error rate is
 *   P_sym_out ≈ (1/n) Σ_{i=t+1}^{n} i · C(n,i) p_s^i (1−p_s)^{n−i}.
 */
export function rsOutputSymbolErrorProb(code: RSCode, ps: number): number {
  if (ps <= 0) return 0
  if (ps >= 1) return 1
  const n = code.n
  let sum = 0
  const lp = Math.log(ps)
  const lq = Math.log(1 - ps)
  for (let i = code.t + 1; i <= n; i++) {
    sum += (i / n) * Math.exp(lnChoose(n, i) + i * lp + (n - i) * lq)
  }
  return Math.min(1, sum)
}

// ---------------------------------------------------------------------------
// A tiny deterministic RNG (mirrors comms/mulberry32) so demos are reproducible.
// ---------------------------------------------------------------------------

export function rsRng(seed: number): () => number {
  let s = seed >>> 0
  return () => {
    s |= 0
    s = (s + 0x6d2b79f5) | 0
    let t = Math.imul(s ^ (s >>> 15), 1 | s)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** Random data symbols for a code (each in [0, 2^m)). */
export function randomMessage(code: RSCode, rng: () => number): number[] {
  const out = new Array(code.k)
  for (let i = 0; i < code.k; i++) out[i] = Math.floor(rng() * code.field.size)
  return out
}
